// Portal Pads. Hand-written (not generated) - edit freely.
//
// mymod:portal_pad is a flat glowing block (blocks/portal_pad.json, generated by
// tools/gen_portal.py). Pads of the same colour are linked: step onto one and you come out on
// top of the other, anywhere in the world, in any dimension. Every new pad is purple, so any
// two pads work straight away. Use a dye on a pad to change its colour (and so which pads it's
// linked to); use it with an empty hand to see what it's linked to. With three or more pads of
// one colour they go round in a loop, in the order they were placed.
//
// Players and creatures (mobs, animals, Big Cats) travel; items, arrows, vehicles and bosses don't.
// After arriving you have to step off the pad and back on to go back.
//
// Every placed pad is remembered in a world dynamic property (bigcat_portal_<dim>_<x>_<y>_<z>
// = {"c": colour, "n": placement number}), so the partner can be found even when it's far away
// in an unloaded chunk. Pads that turn out to be gone are forgotten the next time they're checked.

import { world, system, MolangVariableMap } from "@minecraft/server";
import { COLORS, PAD_STATE } from "./portal_colors.js";

const PAD_ID = "mymod:portal_pad";
const PREFIX = "bigcat_portal_";
const COUNTER = "bigcat_portal_counter";
const SWIRL = "mymod:portal_swirl";

const SCAN_TICKS = 2;
const AMBIENT_TICKS = 10;
const NEAR_PLAYER = 48; // only look for travellers on pads this close to a player
const AMBIENT_RANGE = 24;
const COOLDOWN_TICKS = 10;

// Never teleported: too big, or not creatures.
const IMMUNE = new Set(["minecraft:ender_dragon", "minecraft:wither", "minecraft:warden", "minecraft:elder_guardian"]);

/** key -> { key, dimId, pos, c, n } */
const pads = new Map();
/** entityId -> key of the pad they arrived on (no going back until they step off) */
const arrivedOn = new Map();
/** entityId -> tick of their last trip */
const lastTrip = new Map();
let loaded = false;

function safe(fn) {
  try {
    return fn();
  } catch {
    return undefined;
  }
}

function padKey(dimId, p) {
  return `${dimId.replace("minecraft:", "")}_${p.x}_${p.y}_${p.z}`;
}

function parseKey(key) {
  const m = /^(.+)_(-?\d+)_(-?\d+)_(-?\d+)$/.exec(key);
  if (!m) return undefined;
  return { dimId: `minecraft:${m[1]}`, pos: { x: Number(m[2]), y: Number(m[3]), z: Number(m[4]) } };
}

// --------------------------------------------------------------------------- the pad list

function load() {
  if (loaded) return;
  loaded = true;
  for (const id of world.getDynamicPropertyIds()) {
    if (!id.startsWith(PREFIX) || id === COUNTER) continue;
    const key = id.slice(PREFIX.length);
    const where = parseKey(key);
    const data = safe(() => JSON.parse(String(world.getDynamicProperty(id))));
    if (where && data) pads.set(key, { key, ...where, c: data.c ?? 0, n: data.n ?? 0 });
  }
}

function save(pad) {
  pads.set(pad.key, pad);
  world.setDynamicProperty(PREFIX + pad.key, JSON.stringify({ c: pad.c, n: pad.n }));
}

function forget(key) {
  pads.delete(key);
  world.setDynamicProperty(PREFIX + key, undefined);
}

function colorOf(block) {
  return safe(() => block.permutation.getState(PAD_STATE)) ?? 0;
}

function remember(dimId, pos, c) {
  const key = padKey(dimId, pos);
  const old = pads.get(key);
  let n = old?.n;
  if (n === undefined) {
    n = Number(world.getDynamicProperty(COUNTER) ?? 0) + 1;
    world.setDynamicProperty(COUNTER, n);
  }
  const pad = { key, dimId, pos: { x: pos.x, y: pos.y, z: pos.z }, c, n };
  save(pad);
  return pad;
}

/** The pad's block if its chunk is loaded: a block, null (gone / not a pad), or undefined (not loaded). */
function padBlock(pad) {
  const block = safe(() => world.getDimension(pad.dimId).getBlock(pad.pos));
  if (!block) return undefined;
  return block.typeId === PAD_ID ? block : null;
}

/** Bring a pad's record up to date with the world. Returns false if the pad is gone. */
function check(pad) {
  const block = padBlock(pad);
  if (block === null) {
    forget(pad.key);
    return false;
  }
  if (block && colorOf(block) !== pad.c) save({ ...pad, c: colorOf(block) });
  return true;
}

/** Same-colour pads other than `pad`, in placement order. */
function matching(pad) {
  return [...pads.values()].filter((p) => p.c === pad.c && p.key !== pad.key).sort((a, b) => a.n - b.n);
}

/** Where `pad` leads: the next pad of its colour after it (in placement order), round in a loop. */
function partner(pad) {
  for (let tries = 0; tries < 50; tries++) {
    const others = matching(pad);
    if (!others.length) return undefined;
    const next = others.find((p) => p.n > pad.n) ?? others[0];
    if (check(next) && pads.get(next.key)?.c === pad.c) return pads.get(next.key);
  }
  return undefined;
}

// --------------------------------------------------------------------------- effects

function burst(dimId, pos, c, count) {
  const dim = safe(() => world.getDimension(dimId));
  if (!dim) return;
  const vars = new MolangVariableMap();
  const [r, g, b] = COLORS[c]?.rgb ?? [0.6, 0.2, 0.9];
  vars.setFloat("variable.pr", r);
  vars.setFloat("variable.pg", g);
  vars.setFloat("variable.pb", b);
  for (let i = 0; i < count; i++) {
    safe(() => dim.spawnParticle(SWIRL, { x: pos.x + 0.5, y: pos.y + 0.1 + i * 0.3, z: pos.z + 0.5 }, vars));
  }
}

function tell(player, text) {
  safe(() => player.onScreenDisplay.setActionBar(text));
}

// --------------------------------------------------------------------------- travelling

function canTravel(entity) {
  if (!entity?.isValid || IMMUNE.has(entity.typeId)) return false;
  if (entity.typeId === "minecraft:player") return String(safe(() => entity.getGameMode())).toLowerCase() !== "spectator";
  if (!entity.getComponent("minecraft:health")) return false; // items, arrows, XP orbs...
  if (safe(() => entity.getComponent("minecraft:riding"))) return false; // its vehicle decides
  return !safe(() => entity.matches({ families: ["inanimate"] })); // armor stands, the Mooshroom Drill...
}

function travel(entity, from) {
  const now = system.currentTick;
  if (now - (lastTrip.get(entity.id) ?? -1000) < COOLDOWN_TICKS) return;
  const isPlayer = entity.typeId === "minecraft:player";
  const to = partner(from);
  if (!to) {
    if (isPlayer) tell(entity, `§7No other §f${COLORS[from.c]?.name ?? ""}§7 portal pad yet. Place one to link them.`);
    arrivedOn.set(entity.id, from.key); // don't repeat the message every tick
    return;
  }
  // Creatures only go to loaded places; players load the place they go to.
  if (!isPlayer && padBlock(to) === undefined) return;
  const dest = { x: to.pos.x + 0.5, y: to.pos.y + 0.1, z: to.pos.z + 0.5 };
  const ok = safe(() => (entity.teleport(dest, { dimension: world.getDimension(to.dimId), keepVelocity: false }), true));
  if (!ok) return;
  lastTrip.set(entity.id, now);
  arrivedOn.set(entity.id, to.key);
  burst(from.dimId, from.pos, from.c, 4);
  burst(to.dimId, to.pos, to.c, 4);
  const fromCenter = { x: from.pos.x + 0.5, y: from.pos.y + 0.5, z: from.pos.z + 0.5 };
  safe(() => world.getDimension(from.dimId).playSound("mob.endermen.portal", fromCenter));
  system.run(() => safe(() => world.getDimension(to.dimId).playSound("mob.endermen.portal", dest)));
}

function onPad(entity, pos) {
  const l = entity.location;
  return l.x >= pos.x && l.x < pos.x + 1 && l.z >= pos.z && l.z < pos.z + 1 && l.y >= pos.y - 0.1 && l.y < pos.y + 0.8;
}

system.runInterval(() => {
  load();
  const players = world.getAllPlayers();
  const stillOn = new Set();
  for (const pad of [...pads.values()]) {
    const near = players.some(
      (p) => p.dimension.id === pad.dimId && Math.hypot(p.location.x - pad.pos.x, p.location.z - pad.pos.z) < NEAR_PLAYER,
    );
    if (!near) continue;
    const block = padBlock(pad);
    if (block === undefined) continue;
    if (!check(pad)) continue;
    const dim = block.dimension;
    const center = { x: pad.pos.x + 0.5, y: pad.pos.y, z: pad.pos.z + 0.5 };
    for (const e of safe(() => dim.getEntities({ location: center, maxDistance: 1.5 })) ?? []) {
      if (!onPad(e, pad.pos) || !canTravel(e)) continue;
      if (arrivedOn.get(e.id) === pad.key) {
        stillOn.add(e.id);
        continue;
      }
      travel(e, pads.get(pad.key) ?? pad);
      stillOn.add(e.id);
    }
  }
  // stepped off the pad they arrived on: they can use it again
  for (const id of arrivedOn.keys()) if (!stillOn.has(id)) arrivedOn.delete(id);
  const now = system.currentTick;
  for (const [id, tick] of lastTrip) if (now - tick > COOLDOWN_TICKS) lastTrip.delete(id);
}, SCAN_TICKS);

// a gentle swirl over pads near players
system.runInterval(() => {
  load();
  const players = world.getAllPlayers();
  for (const pad of pads.values()) {
    const near = players.some(
      (p) => p.dimension.id === pad.dimId && Math.hypot(p.location.x - pad.pos.x, p.location.z - pad.pos.z) < AMBIENT_RANGE,
    );
    if (near && padBlock(pad)) burst(pad.dimId, pad.pos, pad.c, 1);
  }
}, AMBIENT_TICKS);

// --------------------------------------------------------------------------- placing, breaking, dyeing

world.afterEvents.playerPlaceBlock.subscribe((ev) => {
  if (ev.block.typeId !== PAD_ID) return;
  load();
  const pad = remember(ev.dimension.id, ev.block.location, colorOf(ev.block));
  const others = matching(pad).length;
  const name = COLORS[pad.c]?.name ?? "";
  tell(
    ev.player,
    others
      ? `§d${name} portal pad placed: §flinked! Step on it to travel.`
      : `§d${name} portal pad placed. §fPlace another ${name.toLowerCase()} one to link them. Dye it to change colour.`,
  );
  burst(pad.dimId, pad.pos, pad.c, 3);
});

world.afterEvents.playerBreakBlock.subscribe((ev) => {
  if (ev.brokenBlockPermutation?.type?.id !== PAD_ID) return;
  load();
  forget(padKey(ev.dimension.id, ev.block.location));
});

function dyeColor(itemId) {
  return COLORS.findIndex((c) => c.dyes.includes(itemId));
}

function useOneFromHand(player) {
  if (String(safe(() => player.getGameMode())).toLowerCase() === "creative") return;
  const container = player.getComponent("minecraft:inventory")?.container;
  const slot = player.selectedSlotIndex;
  const item = container?.getItem(slot);
  if (!item) return;
  if (item.amount > 1) {
    item.amount -= 1;
    container.setItem(slot, item);
  } else {
    container.setItem(slot, undefined);
  }
}

function describe(player, block) {
  load();
  const pad = pads.get(padKey(block.dimension.id, block.location)) ?? remember(block.dimension.id, block.location, colorOf(block));
  const name = COLORS[pad.c]?.name ?? "";
  const to = partner(pad);
  if (!to) {
    tell(player, `§d${name} portal pad: §fnot linked yet. Place another ${name.toLowerCase()} pad.`);
    return;
  }
  const where = `${to.pos.x}, ${to.pos.y}, ${to.pos.z}${to.dimId === pad.dimId ? "" : ` (${to.dimId.replace("minecraft:", "")})`}`;
  const count = matching(pad).length + 1;
  tell(player, `§d${name} portal pad: §fgoes to ${where}${count > 2 ? ` (${count} ${name.toLowerCase()} pads in a loop)` : ""}`);
}

world.beforeEvents.playerInteractWithBlock.subscribe((ev) => {
  if (!ev.isFirstEvent || ev.block.typeId !== PAD_ID) return;
  const itemId = ev.itemStack?.typeId;
  const c = itemId ? dyeColor(itemId) : -1;
  if (itemId && c < 0) return; // holding something else: let it do its normal thing
  ev.cancel = true;
  const { player, block } = ev;
  system.run(() => {
    if (!block.isValid || block.typeId !== PAD_ID) return;
    if (c < 0 || c === colorOf(block)) {
      describe(player, block);
      return;
    }
    safe(() => block.setPermutation(block.permutation.withState(PAD_STATE, c)));
    load();
    remember(block.dimension.id, block.location, c);
    useOneFromHand(player);
    safe(() => block.dimension.playSound("random.pop", block.location, { pitch: 1.4 }));
    burst(block.dimension.id, block.location, c, 3);
    describe(player, block);
  });
});

world.afterEvents.playerLeave.subscribe((ev) => {
  arrivedOn.delete(ev.playerId);
  lastTrip.delete(ev.playerId);
});
